test("report BOM is the native builder output with mixed parts intact", () => {
  const project = realisticProject();
  const expected = bom.buildBomRows(project);
  const value = report.buildHarnessReportModel(project, SAFE_SVG);
  assert.deepEqual(value.bomRows, expected);
  assert.deepEqual(
    value.bomRows
      .filter((row) => row.category === "Crimp contact")
      .map(({ mpn, quantity }) => ({ mpn, quantity })),
    [
      { mpn: "CONTACT-A", quantity: 2 },
      { mpn: "CONTACT-B", quantity: 1 },
    ],
  );
  assert.equal(value.bomRows.find((row) => row.mpn === "SEAL-A").quantity, 1);
});

test("legacy projects without termination metadata export correctly", () => {
  const connector = component("connector", "legacy-x1", "X1");
  const cable = component("wire", "legacy-w1", "W1");
  const legacy = model.normalizeProject({
    schemaVersion: 2,
    title: "Legacy harness",
    components: [connector, cable],
    links: [
      {
        id: "legacy-link",
        from: { nodeId: connector.id, portId: "pin:1", side: "right" },
        to: { nodeId: cable.id, portId: "wire:1", side: "left" },
      },
    ],
  }).project;
  const value = report.buildHarnessReportModel(legacy, SAFE_SVG);
  assert.deepEqual(value.terminations, []);
  assert.match(
    report.renderHarnessReportHtml(value),
    /No explicit termination metadata is assigned\./,
  );
});

test("HTML escapes malicious text and preserves multiline notes", () => {
  const project = realisticProject();
  project.title = '<script>alert("title")</script> & test';
  project.notes = "Assembly & release\n\n<script>alert('notes')</script>\n- Keep <clear>";
  project.components[0].notes = "Line one\nLine <two> & 'three'";
  const html = report.renderHarnessReportHtml(
    report.buildHarnessReportModel(project, SAFE_SVG),
  );
  assert.doesNotMatch(html, /<script>alert/);
  assert.match(
    html,
    /&lt;script&gt;alert\(&quot;title&quot;\)&lt;\/script&gt; &amp; test/,
  );
  assert.match(html, /SENSE &lt;HI&gt;/);
  assert.match(html, /Line one\nLine &lt;two&gt; &amp; &#39;three&#39;/);
  assert.match(
    html,
    /Assembly &amp; release\n\n&lt;script&gt;alert\(&#39;notes&#39;\)&lt;\/script&gt;\n- Keep &lt;clear&gt;/,
  );
  assert.match(html, /B &quot;release&quot;/);
});

test("blank harness notes omit the report section and navigation link", () => {
  const project = realisticProject();
  project.notes = " \n\n ";
  const html = report.renderHarnessReportHtml(
    report.buildHarnessReportModel(project, SAFE_SVG),
  );
  assert.doesNotMatch(html, /id="notes"/);
  assert.doesNotMatch(html, /href="#notes"/);
});

test("embedded images remain while blob and external images are omitted", () => {
  const project = realisticProject();
  project.components.find((item) => item.designator === "X1").photo = {
    dataUrl: "blob:http://localhost/unsafe",
    fileName: "bad.png",
    mimeType: "image/png",
    width: 10,
    height: 10,
    alt: "unsafe",
  };
  project.components.find((item) => item.designator === "X10").photo = {
    dataUrl: "https://example.com/connector.png",
    fileName: "external.png",
    mimeType: "image/png",
    width: 10,
    height: 10,
    alt: "external",
  };
  const html = report.renderHarnessReportHtml(
    report.buildHarnessReportModel(project, SAFE_SVG),
  );
  assert.ok(html.includes(PIXEL));
  assert.doesNotMatch(html, /blob:/);
  assert.doesNotMatch(html, /https:\/\/example\.com/);
});

test("SVG sanitizer embeds Graphviz SVG and normalizes image href", () => {
  const sanitized = report.sanitizeDiagramSvg(SAFE_SVG);
  assert.ok(sanitized.startsWith("<svg"));
  assert.match(sanitized, /<svg[^>]*viewBox=/);
  assert.match(sanitized, /<image href="data:image\/png;base64,/);
  assert.match(sanitized, /Harness &amp; diagram/);
  assert.match(sanitized, /X1 &lt;safe&gt;/);
  assert.doesNotMatch(sanitized, /DOCTYPE|<\?xml|xlink:href/);
  const html = report.renderHarnessReportHtml(
    report.buildHarnessReportModel(realisticProject(), SAFE_SVG),
  );
  assert.match(html, /<div class="diagram"><svg/);
  assert.doesNotMatch(html, /src="[^"]+\.svg/);
});

test("SVG sanitizer rejects executable and external content", () => {
  const unsafe = [
    '<svg xmlns="http://www.w3.org/2000/svg"><script>alert(1)</script></svg>',
    '<svg xmlns="http://www.w3.org/2000/svg" onload="alert(1)"></svg>',
    '<svg xmlns="http://www.w3.org/2000/svg"><foreignObject>bad</foreignObject></svg>',
    '<svg xmlns="http://www.w3.org/2000/svg"><image href="javascript:alert(1)" /></svg>',
    '<svg xmlns="http://www.w3.org/2000/svg"><image href="https://example.com/a.png" /></svg>',
    '<svg xmlns="http://www.w3.org/2000/svg"><g style="background:url(x)"></g></svg>',
    '<svg xmlns="http://www.w3.org/2000/svg"><path fill="url(https://example.com/pattern.svg)" /></svg>',
  ];
  for (const svg of unsafe) {
    assert.throws(() => report.sanitizeDiagramSvg(svg));
  }
});

test("standalone HTML has report sections, CSP, and print CSS", () => {
  const project = realisticProject();
  project.notes = "Assembly notes\n\n- Keep TP1 away from power wiring.";
  const html = report.renderHarnessReportHtml(
    report.buildHarnessReportModel(project, SAFE_SVG),
  );
  assert.match(html, /^<!doctype html>/);
  assert.match(html, /<header>/);
  assert.match(html, /<main>/);
  assert.match(html, /id="connectors"/);
  assert.match(html, /id="terminations"/);
  assert.match(html, /id="bom"/);
  assert.match(html, /id="notes"/);
  assert.match(html, /CONTACT-A/);
  assert.match(html, /Assembly notes\n\n- Keep TP1 away from power wiring\./);
  assert.doesNotMatch(html, /id="validation"|Notes \/ Validation|validation warnings/i);
  assert.match(html, /default-src 'none'/);
  assert.match(html, /@media print/);
  assert.match(html, /thead\{display:table-header-group/);
  assert.doesNotMatch(html, /<script|<link|cdn/i);
});

test("HTML cable summary omits endpoint lists and keeps Connection Mapping authoritative", () => {
  const project = realisticProject();
  const bundle = component("bundle", "bundle-summary", "B1");
  bundle.wireCount = 2;
  bundle.wireLabels = ["PAIR_H", "PAIR_L"];
  bundle.colors = ["BUWH", "WHBU"];
  project.components.push(bundle);
  const html = report.renderHarnessReportHtml(
    report.buildHarnessReportModel(project, SAFE_SVG),
  );
  const cables = html.match(
    /<section class="report-section" id="cables">([\s\S]*?)<\/section>/,
  )?.[1];
  assert.ok(cables);
  assert.doesNotMatch(cables, /<th>From<\/th>|<th>To<\/th>/);
  for (const heading of [
    "Designator",
    "Manufacturer",
    "MPN",
    "Length",
    "Conductors",
    "Wire size",
  ]) {
    assert.match(cables, new RegExp(`<th(?: class="[^"]+")?>${heading}<\\/th>`));
  }
  assert.match(cables, /W1/);
  assert.match(cables, /LAPP/);
  assert.match(cables, /CABLE-1/);
  const mapping = html.match(
    /<section class="report-section" id="connection-mapping">([\s\S]*?)<\/section>/,
  )?.[1];
  assert.match(mapping, /<th>From Connector<\/th>/);
  assert.match(mapping, /<th>From Pin<\/th>/);
  assert.match(mapping, /<th>To Connector<\/th>/);
  assert.match(mapping, /<th>To Pin<\/th>/);
  assert.match(html, /id="terminations"/);
  assert.match(html, /Bundle Conductors/);
});

test("connector pinouts stay local while Terminations retain manufacturing data", () => {
  const value = report.buildHarnessReportModel(realisticProject(), SAFE_SVG);
  const html = report.renderHarnessReportHtml(value);
  const x1 = html.match(
    /<article class="connector-card" id="connector-1">([\s\S]*?)<\/article>/,
  )?.[1];
  assert.ok(x1);
  for (const heading of ["Pin", "Label", "Wire / Conductor", "Color"]) {
    assert.match(x1, new RegExp(`<th>${heading.replace("/", "\\/")}<\\/th>`));
  }
  assert.doesNotMatch(
    x1,
    /<th>(?:Wire size|Contact manufacturer|Contact MPN|Seal PN|Strip length)<\/th>/,
  );
  assert.match(x1, /W1 \/ cond\. 1/);
  assert.match(x1, /Red \(RD\)/);
  const terminations = html.match(
    /<section class="report-section" id="terminations">([\s\S]*?)<\/section>/,
  )?.[1];
  assert.match(terminations, /Contact manufacturer/);
  assert.match(terminations, /Contact MPN/);
  assert.match(terminations, /Strip length/);
  assert.match(terminations, /CONTACT-A/);
  assert.match(terminations, /5 mm/);
});

test("simple one-pin connectors share lossless compact classification", () => {
  const project = realisticProject();
  const value = report.buildHarnessReportModel(project, SAFE_SVG);
  assert.equal(
    value.connectors.find((connector) => connector.designator === "X10").compact,
    true,
  );
  assert.equal(
    value.connectors.find((connector) => connector.designator === "X1").compact,
    false,
  );
  const html = report.renderHarnessReportHtml(value);
  const compact = html.match(
    /<article class="connector-card compact-connectors">([\s\S]*?)<\/article>/,
  )?.[1];
  assert.match(compact, /Simple One-Pin Connectors/);
  assert.match(compact, /X10/);
  assert.match(compact, /Remote connector/);
  assert.match(html, /<h3>X1 <span>Controller connector<\/span><\/h3>/);

  project.components.find((component) => component.designator === "X10").notes =
    "Special installation note";
  const special = report.buildHarnessReportModel(project, SAFE_SVG);
  assert.equal(
    special.connectors.find((connector) => connector.designator === "X10").compact,
    false,
  );
  const specialHtml = report.renderHarnessReportHtml(special);
  assert.match(specialHtml, /<h3>X10 <span>Remote connector<\/span><\/h3>/);
  assert.match(specialHtml, /Special installation note/);
});

test("Twisted Pairs restores member colors while bundle detail keeps local context", () => {
  const project = realisticProject();
  const bundle = component("bundle", "bundle-pair", "B1");
  bundle.wireCount = 2;
  bundle.wireLabels = ["DATA+", "DATA-"];
  bundle.colors = ["BUWH", "WHBU"];
  project.components.push(bundle);
  project.twistedPairs.push({
    id: "tp-bundle",
    designator: "TP1",
    members: [
      { kind: "bundle-conductor", bundleId: bundle.id, conductorId: bundle.conductorIds[0] },
      { kind: "bundle-conductor", bundleId: bundle.id, conductorId: bundle.conductorIds[1] },
    ],
    twistPitchMm: 25,
    twistDirection: "Z",
  });
  const html = report.renderHarnessReportHtml(
    report.buildHarnessReportModel(project, SAFE_SVG),
  );
  const pairs = html.match(
    /<section class="report-section" id="twisted-pairs">([\s\S]*?)<\/section>/,
  )?.[1];
  for (const heading of [
    "Pair",
    "Member A",
    "Member A color",
    "Member B",
    "Member B color",
    "Pitch",
    "Direction",
  ]) {
    assert.match(pairs, new RegExp(`<th>${heading}<\\/th>`));
  }
  assert.match(pairs, /Blue \/ White \(BUWH\)/);
  assert.match(pairs, /White \/ Blue \(WHBU\)/);
  assert.match(pairs, /linear-gradient\(to bottom, #3f74b8 0 34%, #f5f5f1/);
  assert.match(pairs, /linear-gradient\(to bottom, #f5f5f1 0 34%, #3f74b8/);
  const conductors = html.match(
    /<article class="cable-components bundle-conductors">([\s\S]*?)<\/article>/,
  )?.[1];
  assert.match(conductors, /<th>Color<\/th>/);
  assert.match(conductors, /<th>Twisted pair<\/th>/);
  assert.match(conductors, /Blue \/ White \(BUWH\)/);
  assert.match(conductors, /TP1 \/ B1:DATA-/);
});

test("report-only BOM designator compression is safe and leaves CSV raw", () => {
  assert.equal(
    report.formatReportDesignators(["J1:1", "J1:2", "J1:3", "J1:4"]),
    "J1:1–4",
  );
  assert.equal(report.formatReportDesignators(["W1", "W2", "W3"]), "W1–W3");
  assert.equal(
    report.formatReportDesignators(["J1:1", "J1:3"]),
    "J1:1, J1:3",
  );
  assert.equal(
    report.formatReportDesignators(["W1", "W2", "W4"]),
    "W1–W2, W4",
  );
  assert.equal(report.formatReportDesignators(["J1", "J2"]), "J1, J2");
  const rows = bom.buildBomRows(realisticProject());
  const before = structuredClone(rows);
  const csv = bom.serializeBomCsv(rows);
  report.formatReportDesignators(["W1", "W2", "W3"]);
  assert.deepEqual(rows, before);
  assert.match(csv, /X1:1, X2:1/);
  assert.doesNotMatch(csv, /X1:1–X2:1/);
});

test("HTML BOM renders shared quantities and natural designators", () => {
  const value = report.buildHarnessReportModel(realisticProject(), SAFE_SVG);
  const html = report.renderHarnessReportHtml(value);
  for (const row of value.bomRows) {
    assert.ok(html.includes(row.mpn || row.description));
    assert.ok(html.includes(`>${bom.formatBomQuantity(row.quantity)}<`));
  }
  assert.match(html, /X1:1, X2:1/);
});

